tool_input.content:
{
  "harness": {
    "name": "Gran-Mestre Hybrid Harness",
    "version": "1.0.0",
    "mode": "MIX",
    "description": "Hybrid AI orchestration harness for local (MI50) and cloud models",
    "hardware": {
      "cpu": "Xeon E5-2699v3",
      "motherboard": "jingsh x99-d8 (x99/c612)",
      "ram": "32GB DDR4 2400MHz",
      "gpu": {
        "model": "MI50",
        "vram_gb": 16,
        "hbm2_bandwidth_tb_s": 1024
      },
      "storage": {
        "primary": "slave A.I. SSD 128GB SATA3",
        "harness_idempotent": true
      }
    },
    "models": {
      "gran_mestre": {
        "name": "Ornith-1.0 9B",
        "quantization": "Q4_K_M",
        "vram_gb": 5.5,
        "location": "local",
        "role": "meta_orchestrator",
        "description": "Stable backbone for control logic"
      },
      "heavy_execution": {
        "name": "Bonsai 27B 1-bit",
        "quantization": "1-bit",
        "vram_gb": 3.9,
        "location": "local",
        "role": "code_generation",
        "parallel_slots": 4,
        "description": "Heavy code generation with multiple parallel slots"
      },
      "filter_fast": {
        "name": "LFM 2.5-1.6B",
        "quantization": "FP8",
        "vram_gb": 1.1,
        "location": "local",
        "role": "instant_checks",
        "description": "Binary validation checks"
      },
      "filter_medium": {
        "name": "Nanbeige 3B",
        "quantization": "4-bit (GGUF/EXL2)",
        "vram_gb": 1.4,
        "location": "local",
        "role": "micro_reviews",
        "description": "Layered text understanding for validation"
      },
      "cloud_moe": {
        "name": "MoE (Cloud)",
        "quantization": "n/a",
        "vram_gb": 0,
        "location": "cloud",
        "role": "architectural_audit",
        "trigger": "Phase 5/6 or 3 consecutive Bonsai failures",
        "description": "Elite consultant for architectural abstraction"
      }
    },
    "vram_budget": {
      "total_gb": 16,
      "models_allocated_gb": 11.9,
      "kv_cache_reserved_gb": 4.1,
      "safety_margin_gb": 0
    },
    "pipeline": {
      "phases": [
        {
          "number": 1,
          "name": "Discovery",
          "tags": ["discovery", "research", "interview", "brainstorming"],
          "model": "Ornith-1.0 9B",
          "filters": ["LFM 2.5", "Nanbeige 3B"],
          "gate": "Gate 1: Direction approval"
        },
        {
          "number": 2,
          "name": "Contract",
          "tags": ["spec", "contract", "design", "validation"],
          "model": "Bonsai 27B 1-bit",
          "filters": ["Nanbeige 3B"],
          "gate": "Gate 2: Spec approval"
        },
        {
          "number": 3,
          "name": "Plan",
          "tags": ["planning", "tdd", "tasks", "decomposition"],
          "model": "Bonsai 27B 1-bit",
          "filters": ["LFM 2.5", "Nanbeige 3B"],
          "gate": "Gate 3: Plan approval",
          "safety_checkpoint": true
        },
        {
          "number": 4,
          "name": "Execution",
          "tags": ["execution", "implementation", "coding", "git"],
          "model": "Bonsai 27B 1-bit",
          "filters": ["LFM 2.5", "Nanbeige 3B"],
          "gate": "None — atomic commits",
          "dev_loop": "N1/ReAct per task"
        },
        {
          "number": 5,
          "name": "Macro Review",
          "tags": ["review", "macro", "architecture", "audit"],
          "model": "Ornith-1.0 9B + MoE (cloud)",
          "filters": ["Nanbeige 3B"],
          "gate": "None — report"
        },
        {
          "number": 6,
          "name": "Delivery",
          "tags": ["delivery", "verification", "release", "memory"],
          "model": "Ornith-1.0 9B + MoE (cloud)",
          "filters": ["LFM 2.5"],
          "gate": "Gate 4: Final report → cerebral memory"
        }
      ]
    },
    "safety_protocol": {
      "sha_checkpoint_phase": 3,
      "git_diff_check": true,
      "rollback_on_failure": true,
      "hestia_validator": true,
      "never_partial_state": true
    },
    "observability": {
      "context_file": ".planning/CONTEXT.md",
      "metrics_format": "[Metrics] Phase: {phase}\n[Metrics] Route: {route}\n[Metrics] Status: {status}",
      "otel_enabled": true,
      "melt_tracking": true,
      "semantic_conventions": "genai"
    },
    "dev_loop": {
      "level_1": {
        "name": "ReAct",
        "use_for": "Trivial tasks (1-3 files)",
        "max_iterations": 3,
        "escalates_to": 2
      },
      "level_2": {
        "name": "Mini Loop",
        "use_for": "Features (1 module, clear requirements)",
        "max_cycles": 2,
        "escalates_to": 3
      },
      "level_3": {
        "name": "Human Loop",
        "use_for": "Epics, architectural decisions, multi-module",
        "termination": "Human decision"
      }
    }
  }
}

