// Estado persistido em .opencode/, sem chamadas remotas.

async function readLocalState(): Promise<Record<string, unknown> | null> {
  try {
    const raw = await readFile(join(directory, CONFIG_DIR, LOCAL_STATE_FILE), "utf-8");
    return JSON.parse(raw) as Record<string, unknown>;
  } catch {
    return null;
  }
}

async function writeLocalState(state: Record<string, unknown>): Promise<void> {
  try {
    await mkdir(join(directory, CONFIG_DIR), { recursive: true });
    const payload = {
      version: LOCAL_STATE_VERSION,
      updatedAt: new Date().toISOString(),
      ...state,
    };
    await writeFile(join(directory, CONFIG_DIR, LOCAL_STATE_FILE), JSON.stringify(payload, null, 2), "utf-8");
  } catch {
    // non-critical
  }
}

