import re, json, pathlib

def extract_patterns(text: str, slug: str) -> dict:
    """Destila padrões reais do README: título, proposito, features, comandos."""
    lines = text.splitlines()
    title = slug
    # título: primeira linha # ou nome repo na primeira linha não-vazia
    for ln in lines[:15]:
        m = re.match(r'^\s*#\s+(.+)', ln)
        if m:
            title = m.group(1).strip()
            break
    purpose = ""
    # primeiro parágrafo após título
    si = 0
    for i, ln in enumerate(lines[:40]):
        if re.match(r'^\s*#', ln):
            si = i
            break
    for ln in lines[si+1:si+8]:
        if ln.strip() and not ln.startswith(('#', '!', '[')) and len(ln.strip()) > 30:
            purpose = ln.strip()
            break
    # features: linhas marcadas com - , ✓, ✔, bullet apontando capabilities
    feats = []
    for ln in lines:
        s = ln.strip()
        if re.match(r'^[-*•✔✓✅]\s+(?:[A-Z\[]|\*\*)', s) and 15 < len(s) < 200:
            feats.append(s[2:].strip().lstrip('* ').strip())
    # dedupe e limita
    seen, out = set(), []
    for f in feats:
        if f not in seen and len(out) < 8:
            seen.add(f); out.append(f)
    return {"slug": slug, "titulo": title, "proposito": purpose, "padroes": out}

