python3 << 'PY'
import json, os, re
d = json.load(open('/home/johncoffee/.config/opencode/oh-my-openagent.json'))
print("oh-my-openagent (tool-calling agentes):")
roles = {'Bonsai (código/arquitetura)': [], 'Ornith (orquestração)': [], 'Nanbeige (workers)': [], 'LFM (ultra-leve)': []}
for k, v in d['agents'].items():
    m = v['model']
    if 'bonsai' in m: roles['Bonsai (código/arquitetura)'].append(k)
    elif 'ornith' in m: roles['Ornith (orquestração)'].append(k)
    elif 'nanbeige' in m: roles['Nanbeige (workers)'].append(k)
    elif 'lfm' in m: roles['LFM (ultra-leve)'].append(k)
for r, ks in roles.items():
    print(f"  {r}: ({len(ks)}) {', '.join(ks)}")
print("\nmodelo fixo nos 56 agentes .md:")
n = {'local-nanbeige': 0, 'local-ornith': 0, 'local-bonsai': 0, 'local-lfm': 0, 'opencode/': 0}
for f in os.listdir('/home/johncoffee/.config/opencode/agents'):
    if not f.endswith('.md'): continue
    txt = open(os.path.join('/home/johncoffee/.config/opencode/agents', f)).read()
    m = re.search(r'^model:\s*(.+)$', txt, re.M)
    if m:
        v = m.group(1).strip()
        for pref in n:
            if v.startswith(pref):
                n[pref] += 1; break
print(f"  {' | '.join(f'{k}: {v}' for k, v in n.items())}")
PY
