python3 - <<'EOF'
import json, pathlib
alv = json.load(open('harness/autofagia/alvos.json'))
cat = {a['slug']: a for a in json.load(open('harness/autofagia/catalogo-padroes.json'))['alvos']}
reg = json.load(open('opencode/config/agents/gran-mestre/agent-registry.json'))
reg_ids = {e.get('id') for e in reg['entries']}
print(f"alvos.json: {len(alv)} | catálogo: {len(cat)} | registry entries: {len(reg_ids)}")
print("\n-- alvos no alvos.json SEM entrada no catálogo --")
for a in alv:
    if a['slug'] not in cat: print(f"  ✗ {a['slug']} (catálogo ausente)")
print("\n-- alvos no catálogo SEM entrada no registry --")
for s in cat:
    if s not in reg_ids and s != 'pxpipe': print(f"  ✗ {s} (registry ausente)")
print("\n-- registry: helenizados com tipo_origem=framework-externo --")
ext = [e['id'] for e in reg['entries'] if (e.get('origem') or {}).get('tipo_origem')=='framework-externo']
print(f"  {len(ext)}: {sorted(ext)}")
EOF

